def append_expansion(banks,row,hi):
    """Append in order: the original question IDs and old room contents stay valid."""
    from collections import Counter
    seen=Counter()
    targets={'F':['STANDARD','BUZZER','SURVIVAL','TEAMS'],'C':['CONSENSUS','WOLF'],'M':['MAJORITY'],'V':['VOTE'],'D':['DRAW'],'N':['NEAREST']}
    for kind,category,ja,en,a,b in ROWS:
        index=seen[kind,category];seen[kind,category]+=1
        if kind=='D':
            q=row(category,'絵で伝えよう：'+ja,'Draw: '+en,'','',opinion=True)
            q['answer']=[ja,en,hi(ja)]
            q['aliases']=[x for x in (a+'|'+b).split('|') if x]
        else:
            q=row(category,ja,en,a,b,opinion=kind!='F')
        q['difficulty']=['EASY','NORMAL','HARD','HARD'][index%4]
        for mode in targets[kind]:banks[mode].append(q.copy())
    assert len(ROWS)==480
    assert len(seen)==120 and set(seen.values())=={4},'Every category must have all six prompt kinds'
    print('Expansion: 20 categories, 480 authored prompts, 800 mode entries')
